effect.shader:
float hash(float n) {
    return fract(sin(n * 12.9898 + seed * 78.233) * 43758.5453123);
}

float hash2(float n, float s) {
    return fract(sin(n * 17.371 + s * 91.713 + seed * 41.17) * 24634.6345);
}

float smoothNoise(float x) {
    float i = floor(x);
    float f = fract(x);

    float a = hash(i);
    float b = hash(i + 1.0);

    f = f * f * (3.0 - 2.0 * f);

    return mix(a, b, f);
}

vec3 saturateColor(vec3 col, float sat) {
    float grey = dot(col, vec3(0.2126, 0.7152, 0.0722));
    return mix(vec3(grey), col, sat);
}

vec3 applyContrast(vec3 col, float con) {
    return (col - 0.5) * con + 0.5;
}

float getFlicker(float t) {
    float timeValue = t * frequency + phase * 100.0;

    float steppedTime = floor(timeValue);
    float mixedTime = mix(timeValue, steppedTime, frameBased);

    float hardRand = hash(floor(timeValue));
    float softRand = smoothNoise(timeValue);

    float randValue = mix(hardRand, softRand, smoothRandom);

    float pulseValue = sin(timeValue * 6.2831853) * 0.5 + 0.5;

    float randomPulse = pulseValue * randValue;

    float finalFlicker = randValue;

    if (flickerMode == 0) {
        finalFlicker = hash(floor(mixedTime));
    }
    else if (flickerMode == 1) {
        finalFlicker = smoothNoise(timeValue);
    }
    else if (flickerMode == 2) {
        finalFlicker = pulseValue;
    }
    else if (flickerMode == 3) {
        finalFlicker = randomPulse;
    }

    finalFlicker = mix(finalFlicker, smoothNoise(timeValue), smoothRandom * 0.5);

    return finalFlicker;
}

void main() {
    vec2 uv = acScreenNorm;
    float t = acTime;

    vec4 src = texture2DCv(inputImg.texture, uv);
    vec3 col = src.rgb;

    float flicker = getFlicker(t);

    /*
        AE/Sapphire-like brightness flicker:
        flicker is remapped from 0..1 to -1..1,
        then bias shifts the brightness direction.
    */

    float centered = (flicker - 0.5) * 2.0;
    centered += bias;
    centered = clamp(centered, -2.0, 2.0);

    float brightnessMult = 1.0 + centered * brightnessAmp;

    /*
        Strobe simulation.
    */

    float strobePhase = fract((t * frequency) + phase);
    float strobeMask = step(strobePhase, strobeWidth);
    float strobeMult = mix(1.0, strobeMask * 2.0, strobeAmount);

    brightnessMult *= strobeMult;

    col *= baseBrightness;
    col *= brightnessMult;

    /*
        Sapphire-style independent RGB flicker.
    */

    float rt = t * frequency + 13.1 + phase * 50.0;
    float gt = t * frequency + 37.7 + phase * 80.0;
    float bt = t * frequency + 91.3 + phase * 120.0;

    float rNoise = mix(hash2(floor(rt), 1.0), smoothNoise(rt), smoothRandom);
    float gNoise = mix(hash2(floor(gt), 2.0), smoothNoise(gt), smoothRandom);
    float bNoise = mix(hash2(floor(bt), 3.0), smoothNoise(bt), smoothRandom);

    float rFlick = 1.0 + ((rNoise - 0.5) * 2.0) * colorAmp * redAmount;
    float gFlick = 1.0 + ((gNoise - 0.5) * 2.0) * colorAmp * greenAmount;
    float bFlick = 1.0 + ((bNoise - 0.5) * 2.0) * colorAmp * blueAmount;

    col *= vec3(rFlick, gFlick, bFlick);

    col = applyContrast(col, contrast);
    col = saturateColor(col, saturation);
    col = clamp(col, 0.0, 1.0);

    vec4 result = vec4(col, src.a);

    gl_FragColor = mix(src, result, blend);
}
